     底部：32px + safe area（不是贴底）
     左右：各24px留白（dock在中间飘着）
     这才是iOS 26 floating capsule的精髓 */
  padding: 0 24px calc(32px + env(safe-area-inset-bottom));
  pointer-events: none;
}

.tabbar-dock {
  pointer-events: auto;
  position: relative;
