  align-items: center;
  justify-content: center;
  /* 宽度自适应内容，不撑满！min-width保证5个tab能放下，max-width限制不会太宽 */
  width: fit-content;
  min-width: 260px;
  max-width: 340px;
  height: 58px;
  margin: 0 auto;
  padding: 4px 5px;
  border-radius: 29px;
  /* ===== Liquid Glass L1导航层玻璃（铁律14）=====
     填充：0.08极薄（不是白瓷块0.5+）
     亮边：0.65白边（玻璃边缘反光，不是inset高光）
     blur：12px（透镜感，不是大模糊磨砂）
     阴影：柔影三层，只"浮"不"框" */
  background: linear-gradient(160deg, rgba(255,255,255,0.08), rgba(255,252,245,0.06));
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  backdrop-filter: blur(12px) saturate(180%);
  box-shadow:
    0 0.5px 0 0 rgba(255,255,255,0.65),
    0 1px 1.5px rgba(120,90,30,0.02),
    0 6px 20px -8px rgba(120,90,30,0.08),
    0 20px 48px -20px rgba(120,90,30,0.12);
}

/* 滑动透镜：金色玻璃聚焦效果，选中项的"透镜" */
.tab-lens {
  position: absolute;
  top: 4px;
  left: 5px;
  height: 50px;
  border-radius: 25px;
  background: linear-gradient(145deg,
    rgba(var(--zg-primary-rgb, 186,117,23), 0.10),
    rgba(var(--zg-accent-rgb, 232,213,163), 0.06)
  );
  box-shadow:
    0 0.5px 0 0 rgba(255,255,255,0.5),
    0 1px 2px rgba(var(--zg-primary-rgb, 186,117,23), 0.06),
    0 4px 12px -4px rgba(var(--zg-primary-rgb, 186,117,23), 0.10);
  transform: translate3d(0, 0, 0);
  transition: transform 0.55s cubic-bezier(0.34, 1.56, 0.64, 1),
              width 0.55s cubic-bezier(0.34, 1.56, 0.64, 1);
  z-index: 0;
